// <auto-generated />
namespace Fanex.Logging.Sentry.RavenClient
{
    using System;
    using System.Diagnostics;
    using System.Threading.Tasks;
    using Newtonsoft.Json;
    using Newtonsoft.Json.Serialization;
    using SharpRaven;
    using SharpRaven.Data;

    public class SentryLogging : ILogEngine
    {
        private const string sentryScriptDefault = "https://cdn.ravenjs.com/3.27.0/raven.min.js";
        private readonly SentryEngineOptions sentryOptions;
        private readonly string sentryScript;

        private static readonly JsonSerializerSettings jsonSerializerSettings = new JsonSerializerSettings
        {
            Formatting = Formatting.Indented,
            ContractResolver = new CamelCasePropertyNamesContractResolver()
        };

        public SentryLogging(
            SentryEngineOptions sentryOptions,
            string sentryScript = sentryScriptDefault)
        {
            this.sentryOptions = sentryOptions ?? throw new ArgumentNullException(nameof(sentryOptions));
            this.sentryScript = sentryScript;
        }

        private static RavenClient CreateRaventClient(
            SentryEngineOptions sentryEngineOptions,
            string category = null)
            => new RavenClient(
                    sentryEngineOptions.Dsn,
                    sentryUserFactory: sentryEngineOptions.GetUserInfo != null
                        ? new SentryUserFactory(sentryEngineOptions.GetUserInfo)
                        : null)
            {
                Environment = sentryEngineOptions.Environment ?? category,
                Release = sentryEngineOptions.Release,
                Timeout = TimeSpan.FromSeconds(sentryEngineOptions.WriteLogTimeoutSeconds)
            };

        internal SentryEngineOptions GetSentryOptions
            => sentryOptions
                ?? throw new InvalidOperationException("Please init Fanex.Logging for Sentry before using.");

        public void Write(string message, TraceEventType severity, string category)
        {
            var ravenClient = CreateRaventClient(sentryOptions, category);

            ravenClient.Capture(new SentryEvent(new SentryMessage(message))
            {
                Level = GetLogLevel(severity)
            });
        }

        private static ErrorLevel GetLogLevel(TraceEventType severity)
        {
            switch (severity)
            {
                case TraceEventType.Information:
                    return ErrorLevel.Info;

                case TraceEventType.Warning:
                    return ErrorLevel.Warning;

                case TraceEventType.Error:
                    return ErrorLevel.Error;

                case TraceEventType.Critical:
                    return ErrorLevel.Fatal;

                case TraceEventType.Verbose:
                    return ErrorLevel.Debug;

                default:
                    return ErrorLevel.Error;
            }
        }

        /// <summary>
        /// I got a problem when call CaptureAsync, may be deadlock, so I use sync code here.
        /// </summary>
        public Task WriteAsync(string message, TraceEventType severity, string category)
        {
            Write(message, severity, category);

#if NETSTANDARD2_0 || NET461 || NET5_0_OR_GREATER
            return Task.FromResult(0);
#else
            return Logger.FromResult(0);
#endif
        }

        public string RenderJavascriptLogger()
        {
            var options = GetSentryOptions;
            var user = options.GetUserInfo?.Invoke();

            return string.Join(
                string.Empty,
                string.IsNullOrWhiteSpace(sentryScript)
                    ? string.Empty
                    : $"<script src=\"{sentryScript}\" crossorigin=\"anonymous\"></script>",
                "<script type=\"text/javascript\">",
                $"var ravenOptions = {JsonConvert.SerializeObject(options, jsonSerializerSettings)};",
                $"Raven.config(\"{options.FrontEndDsn ?? options.Dsn}\", ravenOptions).install();",
                user != null
                    ? $"Raven.setUserContext({JsonConvert.SerializeObject(user, jsonSerializerSettings)});"
                    : string.Empty,
                "</script>");
        }
    }
}